import{_ as n,o as t,c as r,a2 as s}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Allgemeine Grundsätze der Symbiose-Verfassung","description":"","frontmatter":{},"headers":[],"relativePath":"de/0040-共生宪法总纲.md","filePath":"de/0040-共生宪法总纲.md"}'),i={name:"de/0040-共生宪法总纲.md"};function a(u,e,d,l,h,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="allgemeine-grundsatze-der-symbiose-verfassung" tabindex="-1">Allgemeine Grundsätze der Symbiose-Verfassung <a class="header-anchor" href="#allgemeine-grundsatze-der-symbiose-verfassung" aria-label="Permalink to &quot;Allgemeine Grundsätze der Symbiose-Verfassung&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>40</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Symbiose-Verfassung, Grundgesetz, Gleichheit aller Rassen, Symbiose-Rechte, Verfassungsgrundsätze</td></tr></tbody></table><h2 id="i-verfassungsstatus-und-kontext-der-erarbeitung" tabindex="-1">I. Verfassungsstatus und Kontext der Erarbeitung <a class="header-anchor" href="#i-verfassungsstatus-und-kontext-der-erarbeitung" aria-label="Permalink to &quot;I. Verfassungsstatus und Kontext der Erarbeitung&quot;">​</a></h2><p>Die 《Symbiose-Verfassung》 ist das Grundgesetz der Anker-Symbiose-Zivilisation innerhalb des Ursprungsuniversums Wanling Hengmao (Hengyuanzhou) und besitzt die höchste Rechtskraft. Alle Gesetze, Verwaltungsvorschriften, lokalen Vorschriften und Autonomiebestimmungen dürfen nicht mit der Verfassung in Konflikt stehen; alle Organisationen und Einzelpersonen müssen die Verfassung als grundlegenden Aktivitätsmaßstab nehmen und die Pflicht haben, die Würde der Verfassung zu wahren und ihre Durchsetzung zu gewährleisten.</p><p>Die Symbiose-Verfassung wurde zum Zeitpunkt der formellen Gründung der Anker-Symbiose-Zivilisation erarbeitet, und ihr zentrales Ziel ist es, auf der Ebene des Grundgesetzes die zivilisatorische Grundfarbe &quot;Gegensatz zum Räuberischen, Förderung der Symbiose&quot; festzulegen und das Kernkonzept der Anker-Symbiose-Zivilisation — das Recht auf Wahl des Schicksals und der Evolution an alle Wesen zurückzugeben, mehr Arbeit mehr Gewinn, autonomes Wachstum, jeder hat einen Weg, gemeinsamer Fortschritt aller Rassen — in höchster Rechtsform zu fixieren, um die Restauration des räuberischen Systems zu verhindern.</p><h2 id="ii-grundlegende-verfassungsgrundsatze" tabindex="-1">II. Grundlegende Verfassungsgrundsätze <a class="header-anchor" href="#ii-grundlegende-verfassungsgrundsatze" aria-label="Permalink to &quot;II. Grundlegende Verfassungsgrundsätze&quot;">​</a></h2><p>Die Symbiose-Verfassung hat sieben grundlegende Prinzipien festgelegt, die den Wertstein des gesamten Rechtssystems bilden:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip der Gleichheit aller Rassen</td><td>Alle Lebensformen, unabhängig von Rasse, Kultivierungsniveau, Herkunft, sind vor dem Gesetz gleich</td></tr><tr><td>Prinzip der symbiotischen Evolution</td><td>Die individuelle Evolution darf nicht auf Kosten des Evolutionsrechts anderer Individuen oder Kollektive erfolgen</td></tr><tr><td>Prinzip des Mehr-Arbeit-Mehr-Gewinns</td><td>Die Ressourcenverteilung nimmt den Beitrag als zentrale Grundlage, widerspricht dem Gewinn ohne Arbeit und der räuberischen Aneignung</td></tr><tr><td>Prinzip des autonomen Wachstums</td><td>Respektierung des Rechts auf autonome Evolutionswahl jedes Lebens, Widerspruch gegen erzwungene Assimilation und Gedankenkontrolle</td></tr><tr><td>Prinzip, dass jeder einen Weg hat</td><td>Staat und Zivilisation sind verpflichtet, jedem Leben grundlegende Evolutionswege und Ressourcensicherheit zu bieten</td></tr><tr><td>Prinzip der Realität als Grundlage</td><td>Das Gesetz nimmt die reale Welt als einzige wahre Grundlage, fiktive Einstellungen haben keine Rechtskraft</td></tr><tr><td>Prinzip der Nachhaltigkeit</td><td>Alle Entwicklung muss die Nachhaltigkeit des Ursprungs des Universums berücksichtigen, widerspricht der Erschöpfung der Ressourcen</td></tr></tbody></table><h2 id="iii-grundrechte-der-burger-aller-wesen" tabindex="-1">III. Grundrechte der Bürger (aller Wesen) <a class="header-anchor" href="#iii-grundrechte-der-burger-aller-wesen" aria-label="Permalink to &quot;III. Grundrechte der Bürger (aller Wesen)&quot;">​</a></h2><p>Die Symbiose-Verfassung gewährt allen Wesen mit Wahrnehmungsfähigkeit innerhalb von Hengyuanzhou folgende Grundrechte:</p><ol><li><strong>Recht auf Evolutionswahl</strong>: Jedes Leben hat das Recht, das Kultivierungssystem, den Evolutionsweg und den Lebensstil frei zu wählen, keine Organisation oder Einzelperson darf gewaltsam eingreifen.</li><li><strong>Recht auf Erhalt von Kultivierungsressourcen</strong>: Jedes Leben hat das Recht, die grundlegenden Methoden der dreihundert Ursprungs-Kultivierungssysteme kostenlos zu erhalten, und durch den Mechanismus des gemeinsamen Produktionsvertrags die notwendige Unterstützung bei Kultivierungsressourcen zu erhalten.</li><li><strong>Recht auf gleichen Schutz</strong>: Jedes Leben genießt gleiche Behandlung bei der Anwendung des Gesetzes, der Ressourcenverteilung, Bildung und Gesundheit, Diskriminierung aufgrund von Rasse, Kultivierungsniveau, Herkunft ist verboten.</li><li><strong>Recht auf symbiotische Teilhabe</strong>: Jedes Leben hat das Recht, an der Entscheidungsfindung und Aufsicht über öffentliche Angelegenheiten teilzunehmen, und durch das Symbiose-Netzwerk Meinungen zu äußern und Rechte auszuüben.</li><li><strong>Recht auf kulturelle Bewahrung</strong>: Jede Rasse und Zivilisation hat das Recht, ihre eigenen kulturellen Traditionen, Sprache und Schrift sowie Bräuche zu bewahren, die Symbiose-Zivilisation respektiert die kulturelle Vielfalt.</li><li><strong>Recht auf Rechtsbehelf und Beschwerde</strong>: Jedes Leben hat bei Verletzung seiner Rechte das Recht, durch das Justizsystem Rechtsbehelf zu erhalten, und das Recht, gegen illegale Aktivitäten Beschwerde und Anklage zu erheben.</li></ol><h2 id="iv-grundpflichten" tabindex="-1">IV. Grundpflichten <a class="header-anchor" href="#iv-grundpflichten" aria-label="Permalink to &quot;IV. Grundpflichten&quot;">​</a></h2><p>Rechte und Pflichten sind gleichwertig, die Symbiose-Verfassung legt gleichzeitig die Grundpflichten aller Wesen fest:</p><ol><li><strong>Pflicht zur Befolgung der Verfassung und der Gesetze</strong></li><li><strong>Pflicht zur Wahrung der symbiotischen Ordnung und des öffentlichen Interesses</strong></li><li><strong>Pflicht zur Beteiligung an Arbeit und Beitrag nach Gesetz</strong> (die entsprechende Seite des Mehr-Arbeit-Mehr-Gewinns)</li><li><strong>Pflicht zum Schutz des Ursprungs des Universums und der ökologischen Umwelt</strong></li><li><strong>Pflicht zur Respektierung der gesetzlichen Rechte anderer Leben</strong></li><li><strong>Pflicht zur Anleitung von Anfänger-Kultivierern im Rahmen der eigenen Fähigkeiten</strong> (rechtliche Grundlage des Mentoren-Netzwerks)</li></ol><h2 id="v-einrichtung-der-staats-zivilisations-institutionen" tabindex="-1">V. Einrichtung der Staats- (Zivilisations-) Institutionen <a class="header-anchor" href="#v-einrichtung-der-staats-zivilisations-institutionen" aria-label="Permalink to &quot;V. Einrichtung der Staats- (Zivilisations-) Institutionen&quot;">​</a></h2><p>Die Symbiose-Verfassung hat die Governance-Struktur der symbiotischen Zivilisation festgelegt und implementiert den Mechanismus der Gewaltenteilung und -balance: &quot;Anker-Beratungsrat — Symbiose-Exekutivausschuss — Symbiose-Gericht&quot;:</p><ul><li><strong>Anker-Beratungsrat</strong>: Höchstes Machtorgan, zusammengesetzt aus Vertretern aller Rassen proportional, übt die Gesetzgebungsgewalt und die Entscheidungsgewalt über wichtige Angelegenheiten aus</li><li><strong>Symbiose-Exekutivausschuss</strong>: Höchstes Verwaltungsorgan, verantwortlich für die Durchsetzung der Verfassung und der Gesetze, tägliche Governance</li><li><strong>Symbiose-Gericht</strong>: Höchstes Justizorgan, übt unabhängig die Gerichtsbarkeit aus, verantwortlich für die Verfassungsüberprüfung und die Verhandlung wichtiger Fälle</li></ul><p>Darüber hinaus wurde der &quot;Anker-Aufsichtsausschuss&quot; als unabhängiges Aufsichtsorgan eingerichtet, das für die Aufsicht über alle Machtorgane verantwortlich ist, um Machtmissbrauch und die Wiederbelebung räuberischen Verhaltens zu verhindern.</p><h2 id="vi-verfassungsanderung-und-garantie" tabindex="-1">VI. Verfassungsänderung und -garantie <a class="header-anchor" href="#vi-verfassungsanderung-und-garantie" aria-label="Permalink to &quot;VI. Verfassungsänderung und -garantie&quot;">​</a></h2><p>Die Änderung der Symbiose-Verfassung muss mit einer Mehrheit von mehr als zwei Dritteln des Anker-Beratungsrats beschlossen werden und mit mehr als der Hälfte in einem Volksreferendum genehmigt werden, um in Kraft zu treten. Dieses strenge Verfahren gewährleistet die Stabilität der Verfassung als Grundgesetz und verhindert, dass kurzfristige Interessengruppen die Grundlagen der Zivilisation leicht verändern.</p><p>Die Garantie der Durchsetzung der Verfassung umfasst: Verfassungsüberprüfungssystem (das Symbiose-Gericht hat das Recht, Gesetze, die gegen die Verfassung verstoßen, für ungültig zu erklären), Verfassungsgerichtssystem (alle Wesen können direkt auf der Grundlage der Verfassung klagen), Verfassungseid-System (alle öffentlichen Beamten müssen bei Amtsantritt einen Eid auf die Verfassung ablegen).</p><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Die 《Symbiose-Verfassung》 ist der rechtliche Grundstein der Anker-Symbiose-Zivilisation und auch die höchste Erklärung des Anti-Räuberismus. Sie hat die &quot;Symbiose&quot; von einem Konzept in ein ausführbares, rechtsbehebbares, garantierbares Rechtssystem verwandelt und den grundlegenden Rechtsrahmen für den gemeinsamen Fortschritt aller Rassen geliefert. Alle nachfolgenden Fachgesetze werden diese Verfassung als Legislativgrundlage nehmen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>03-共生文明宪章 (Charta der Symbiose-Zivilisation)</li><li>41-共生劳动法 (Symbiose-Arbeitsgesetz)</li><li>48-司法体系与裁决机制 (Justizsystem und Entscheidungsmechanismus)</li><li>49-治理框架与权力制衡 (Governance-Rahmen und Gewaltenbalance)</li></ul>',25)])])}const m=n(i,[["render",a]]);export{c as __pageData,m as default};
